// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import { CheckIcon, CopyIcon, ImageIcon, SendIcon, ThumbsUpIcon } from 'lucide-react'

import { Bar, BrowserChrome, DemoStage, DockHeader, type Build } from '@/app/demos/stage'

import { BODY, BOLD_HOOK, CAPTIONS, CSV, DESKTOP, HOOK, MOBILE, PROFILE, UI } from './script'

const SCROLL = 104

const build: Build = ({ tl, q, qa, step, final, move, click, type, wait, cursorOut }) => {
  step(0)
  move('post', { at: 0.3, ax: 0.2, ay: 0.25 })
  click('post')
  type('hook', HOOK, { speed: 0.04 })
  move('bold', { at: '+=0.2' })
  click('bold')
  tl.to(q('hook'), { opacity: 0, duration: 0.12 }, '<')
  tl.set(q('hook'), { text: BOLD_HOOK })
  tl.to(q('hook'), { opacity: 1, duration: 0.25 })

  step(1, '+=0.4')
  move('post', { ax: 0.6, ay: 0.4 })
  type('body', BODY, { speed: 0.012 })
  tl.fromTo(
    qa('preview-text'),
    { clipPath: 'inset(0 0 100% 0)' },
    {
      clipPath: 'inset(0 0 0% 0)',
      duration: 0.6,
      stagger: 0.25,
      ease: 'power2.out',
      immediateRender: false,
    },
    '-=0.4',
  )
  tl.fromTo(
    qa('see-more'),
    { backgroundColor: 'rgba(56,189,248,0.45)' },
    { backgroundColor: 'rgba(56,189,248,0)', duration: 1, stagger: 0.25, immediateRender: false },
    '>-0.1',
  )

  step(2, '+=0.6')
  tl.to(q('panel-body'), { y: -SCROLL, duration: 0.6, ease: 'power2.inOut' })
  move('in-name', { ax: 0.3, dy: -SCROLL })
  click('in-name')
  tl.to(q('ph-name'), { opacity: 0, duration: 0.1 }, '<')
  type('val-name', PROFILE.name, { speed: 0.045 })
  move('in-headline', { ax: 0.3, dy: -SCROLL })
  click('in-headline')
  tl.to(q('ph-headline'), { opacity: 0, duration: 0.1 }, '<')
  type('val-headline', PROFILE.headline, { speed: 0.03 })
  move('copy-csv', { dy: -SCROLL })
  click('copy-csv')
  tl.to(q('copy-icon'), { opacity: 0, duration: 0.15 }, '<')
  tl.fromTo(
    q('copied-icon'),
    { opacity: 0, scale: 0.5 },
    { opacity: 1, scale: 1, duration: 0.3, ease: 'back.out(3)', immediateRender: false },
    '<',
  )
  tl.fromTo(
    q('clipboard'),
    { opacity: 0, y: 6 },
    { opacity: 1, y: 0, duration: 0.3, ease: 'power3.out', immediateRender: false },
    '<',
  )
  cursorOut('+=0.3')
  final()
  wait(1.4)

  tl.set([q('copied-icon'), q('clipboard')], { opacity: 0 }, 0)
  tl.set(qa('preview-text'), { clipPath: 'inset(0 0 100% 0)' }, 0)
}

function Input({ k, placeholder }: { k: string; placeholder: string }) {
  return (
    <span
      data-d={`in-${k}`}
      className="relative flex h-[18px] items-center rounded border border-line-strong bg-black/20 px-1.5 text-[9px]"
    >
      <span data-d={`ph-${k}`} className="absolute left-1.5 text-muted">
        {placeholder}
      </span>
      <span data-d={`val-${k}`} className="truncate text-ink" />
    </span>
  )
}

function Preview({ label, text }: { label: string; text: string }) {
  const cut = text.endsWith('…')
  return (
    <div className="rounded border border-line p-1.5">
      <p className="text-[8.5px] font-medium text-ink">{label}</p>
      <p data-d="preview-text" className="text-[8px] leading-[11px] text-muted">
        {cut ? text.slice(0, -1) : text}
        {cut && (
          <span data-d="see-more" className="rounded-sm px-px text-ink">
            …
          </span>
        )}
      </p>
    </div>
  )
}

function Panel() {
  return (
    <div className="flex h-full flex-col">
      <DockHeader />
      <div className="min-h-0 flex-1 overflow-hidden">
        <div data-d="panel-body" className="flex flex-col gap-2 p-2.5">
          <div className="rounded-xl border border-line bg-ink/[0.03] p-2">
            <p className="text-[10.5px] font-semibold text-ink">{UI.postTitle}</p>
            <div
              data-d="post"
              className="mt-1 h-[58px] overflow-hidden rounded border border-line-strong bg-black/20 px-1.5 py-1 text-[8px] leading-[11px] text-ink"
            >
              <span data-d="hook" />
              <span data-d="body" className="text-ink-soft" />
            </div>
            <div className="mt-1 flex gap-1 text-[8.5px]">
              <span className="rounded bg-ink/10 px-1.5 py-0.5 text-ink-soft">{UI.spacing}</span>
              <span
                data-d="bold"
                className="rounded bg-ink/10 px-1.5 py-0.5 font-semibold text-ink"
              >
                {UI.bold}
              </span>
              <span className="rounded bg-ink/10 px-1.5 py-0.5 italic text-ink-soft">
                {UI.italic}
              </span>
            </div>
            <div className="mt-1.5 grid gap-1">
              <Preview label={UI.mobile} text={MOBILE} />
              <Preview label={UI.desktop} text={DESKTOP} />
            </div>
          </div>
          <div className="relative rounded-xl border border-line bg-ink/[0.03] p-2">
            <p className="text-[10.5px] font-semibold text-ink">{UI.profileTitle}</p>
            <div className="mt-1 grid gap-1">
              <Input k="name" placeholder={UI.name} />
              <Input k="headline" placeholder={UI.headline} />
            </div>
            <span
              data-d="copy-csv"
              className="relative mt-1 flex size-5 items-center justify-center rounded border border-line-strong"
              title={UI.exportCsv}
            >
              <CopyIcon data-d="copy-icon" className="size-2.5 text-ink-soft" />
              <CheckIcon
                data-d="copied-icon"
                className="absolute size-3 text-[#22c55e] opacity-0"
              />
            </span>
            <pre
              data-d="clipboard"
              className="absolute bottom-1.5 left-9 rounded-md border border-line-strong bg-elevated px-1.5 py-1 font-mono text-[7.5px] leading-[10px] text-[#7dd3fc] opacity-0 shadow-lg"
            >
              {CSV}
            </pre>
          </div>
        </div>
      </div>
    </div>
  )
}

export default function Demo() {
  return (
    <DemoStage
      label="LinkedIn Creator Tools bolding a post hook, previewing the mobile and desktop see-more cutoffs and copying a profile as a CSV row"
      steps={CAPTIONS}
      build={build}
    >
      <BrowserChrome url="https://www.linkedin.com/feed/" panel={<Panel />} panelWidth={236}>
        <div className="h-full space-y-2 bg-[#f4f2ee] p-2.5 text-[#191919]">
          <div className="rounded-lg bg-white p-2 shadow-sm">
            <div className="flex items-center gap-2">
              <span className="size-6 rounded-full bg-[#cbd5e1]" />
              <span className="flex-1 rounded-full border border-black/20 px-2 py-1 text-[8.5px] text-black/60">
                Start a post
              </span>
            </div>
            <div className="mt-1.5 flex gap-3 pl-8 text-[8px] text-black/60">
              <span className="flex items-center gap-1">
                <ImageIcon className="size-2.5 text-[#378fe9]" /> Media
              </span>
              <span>Event</span>
              <span>Write article</span>
            </div>
          </div>
          {[0, 1].map((post) => (
            <div key={post} className="rounded-lg bg-white p-2 shadow-sm">
              <div className="flex items-center gap-1.5">
                <span className="size-6 rounded-full bg-[#0a66c2]/20" />
                <div className="flex-1 space-y-1">
                  <Bar w="38%" className="h-1.5 bg-black/25" />
                  <Bar w="56%" className="h-1 bg-black/10" />
                </div>
              </div>
              <div className="mt-2 space-y-1">
                <Bar w="94%" className="h-1.5 bg-black/12" />
                <Bar w="88%" className="h-1.5 bg-black/12" />
                <span className="flex items-center gap-1">
                  <Bar w="40%" className="h-1.5 bg-black/12" />
                  <span className="text-[8px] text-black/50">…see more</span>
                </span>
              </div>
              <div className="mt-2 flex gap-4 border-t border-black/10 pt-1.5 text-[8px] text-black/60">
                <span className="flex items-center gap-1">
                  <ThumbsUpIcon className="size-2.5" /> Like
                </span>
                <span>Comment</span>
                <span className="flex items-center gap-1">
                  <SendIcon className="size-2.5" /> Send
                </span>
              </div>
            </div>
          ))}
        </div>
      </BrowserChrome>
    </DemoStage>
  )
}
